fn sum_bad(v: &[i32]) -> i32 {
    let mut total = 0;
    for &x in v {
        total += x;
    }
    total
}

fn sum_good(v: &[i32]) -> i32 {
    v.iter().sum()
}

fn benchmark() {
    let v = vec![1; 1_000_000];

    let start = std::time::Instant::now();
    let _ = sum_bad(&v);
    println!("bad: {:?}", start.elapsed());

    let start = std::time::Instant::now();
    let _ = sum_good(&v);
    println!("good: {:?}", start.elapsed());
